-- The shop, as the Firebird tests seed it (a Firebird container in CI, a local server for the Playwright flow): the
-- same rows as shop.sqlite, with what Firebird can say about itself (identity keys, comments, a unique email, an
-- index, a text BLOB, a view). Names are unquoted, so Firebird keeps them in upper case. One statement per block.
CREATE TABLE customers (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  email VARCHAR(255) UNIQUE,
  signed_up DATE,
  active BOOLEAN DEFAULT TRUE
);
COMMENT ON TABLE customers IS 'People who have ordered';
COMMENT ON COLUMN customers.email IS 'Lower case';
CREATE TABLE orders (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  customer_id INTEGER NOT NULL,
  total DECIMAL(10, 2),
  placed_at TIMESTAMP,
  status VARCHAR(10) DEFAULT 'placed' NOT NULL,
  notes BLOB SUB_TYPE TEXT,
  CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers (id)
);
CREATE INDEX orders_customer ON orders (customer_id);
CREATE VIEW order_totals AS SELECT c.name, count(o.id) AS orders, sum(o.total) AS total FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.name;
